package main

import (
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"

	"goimports-reviser/reviser"
)

const (
	version = "3.0.0-20260303205914-9926ea38658f"
	tag     = "v3.0.0-20260303205914-9926ea38658f"
	built   = "go1.26.0"
	source  = "github.com/incu6us/goimports-reviser/v3"
)

var (
	filePath              = flag.String("file-path", "", "Deprecated. Put file name as an argument(last item) of command line.")
	projectName           = flag.String("project-name", "", "Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
	companyPrefixes       = flag.String("company-prefixes", "", "Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
	importsOrder          = flag.String("imports-order", "std,general,company,project", `Your imports groups can be sorted in your way. 
	std - std import group; 
	general - libs for general purpose; 
	company - inter-org or your company libs(if you set '-company-prefixes'-option, then 4th group will be split separately. In other case, it will be the part of general purpose libs); 
	project - your local project dependencies;
	blanked - imports with "_" alias;
	dotted - imports with "." alias.
	Optional parameter.`)
	output                = flag.String("output", "file", `Can be "file", "write" or "stdout". Whether to write the formatted content back to the file or to stdout. When "write" together with "-list-diff" will list the file name and write back to the file. Optional parameter.`)
	listDiff              = flag.Bool("list-diff", false, "Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
	setExitStatus         = flag.Bool("set-exit-status", false, "set the exit status to 1 if a change is needed/made. Optional parameter.")
	rmUnused              = flag.Bool("rm-unused", false, "Remove unused imports. Optional parameter.")
	setAlias              = flag.Bool("set-alias", false, "Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
	format                = flag.Bool("format", false, "Option will perform additional formatting. Optional parameter.")
	recursive             = flag.Bool("recursive", false, "Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
	applyToGeneratedFiles = flag.Bool("apply-to-generated-files", false, "Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
	separateNamed         = flag.Bool("separate-named", false, "Option will separate named imports from the rest of the imports, per group. Optional parameter.")
	local                 = flag.String("local", "", "Deprecated")
	excludes              = flag.String("excludes", "", "Exclude files or dirs, example: '.git/,proto/*.go'.")
	useCache              = flag.Bool("use-cache", false, "Use cache to improve performance. Optional parameter.")
	showVersion           = flag.Bool("version", false, "Show version information")
	versionOnly           = flag.Bool("version-only", false, "Show only the version string")
)

func main() {
	flag.Parse()

	if *showVersion {
		fmt.Printf("version: %s\nbuilt with: %s\ntag: %s\ncommit: n/a\nsource: %s\n", version, built, tag, source)
		printUsageAndExit()
		return
	}

	if *versionOnly {
		fmt.Println(version)
		return
	}

	args := flag.Args()

	// Collect paths from args and deprecated -file-path
	var paths []string
	if len(args) > 0 {
		paths = append(paths, args...)
	}

	filePathDeprecated := false
	if *filePath != "" {
		paths = append(paths, *filePath)
		filePathDeprecated = true
	}

	if len(paths) == 0 {
		printUsageAndExit()
		log.Fatal("no file(s) or directory(ies) specified on input")
		return
	}

	// Validate imports-order
	orderParts := strings.Split(*importsOrder, ",")
	hasStd := false
	hasGeneral := false
	hasCompany := false
	hasProject := false
	for _, p := range orderParts {
		switch strings.TrimSpace(p) {
		case "std":
			hasStd = true
		case "general":
			hasGeneral = true
		case "company":
			hasCompany = true
		case "project":
			hasProject = true
		}
	}
	if !hasStd || !hasGeneral || !hasCompany || !hasProject {
		printUsageAndExit()
		log.Fatal("use default at least 4 parameters to sort groups of your imports: \"std,general,company,project\"")
		return
	}

	log.Printf("Paths: %v", paths)

	options := reviser.Options{
		ProjectName:           *projectName,
		CompanyPrefixes:       *companyPrefixes,
		ImportsOrder:          *importsOrder,
		Output:                *output,
		ListDiff:              *listDiff,
		SetExitStatus:         *setExitStatus,
		RemoveUnused:          *rmUnused,
		SetAlias:              *setAlias,
		Format:                *format,
		Recursive:             *recursive,
		ApplyToGeneratedFiles: *applyToGeneratedFiles,
		SeparateNamed:         *separateNamed,
		Excludes:              *excludes,
		UseCache:              *useCache,
	}

	exitCode := 0

	// Handle ./... special case
	if len(paths) == 1 && paths[0] == "./..." {
		log.Printf("Processing %s", paths[0])
		changed, err := reviser.ProcessDirectory(".", true, options)
		if err != nil {
			log.Printf("Failed to process: %v", err)
			os.Exit(1)
		}
		if *setExitStatus && changed {
			exitCode = 1
		}
	} else {
		for _, path := range paths {
			log.Printf("Processing %s", path)
			err := processPath(path, options, &exitCode)
			if err != nil {
				log.Printf("Failed to fix file: %v", err)
				if exitCode == 0 {
					exitCode = 1
				}
			}
		}
	}

	if filePathDeprecated {
		log.Printf("-file-path is deprecated. Put file name(s) as last argument to the command(Example: goimports-reviser -rm-unused -set-alias -format goimports-reviser/main.go)")
		log.Printf("All changes to file are applied, but command-line syntax should be fixed")
		os.Exit(1)
	}

	os.Exit(exitCode)
}

func processPath(path string, options reviser.Options, exitCode *int) error {
	// Check if it's a directory
	info, err := os.Stat(path)
	if err != nil {
		return err
	}

	if info.IsDir() {
		changed, err := reviser.ProcessDirectory(path, options.Recursive, options)
		if err != nil {
			return err
		}
		if options.SetExitStatus && changed {
			*exitCode = 1
		}
		return nil
	}

	// It's a file
	if !strings.HasSuffix(path, ".go") {
		return nil
	}

	absPath, err := filepath.Abs(path)
	if err != nil {
		return err
	}

	changed, result, err := reviser.ProcessFile(absPath, options)
	if err != nil {
		return err
	}

	if options.SetExitStatus && changed {
		*exitCode = 1
	}

	switch options.Output {
	case "stdout":
		fmt.Print(string(result))
	case "write":
		if changed {
			if options.ListDiff {
				fmt.Println(absPath)
			}
			if err := os.WriteFile(absPath, result, 0644); err != nil {
				return err
			}
		} else if options.ListDiff {
			// still list even if not changed? Let me check
		}
	case "file", "":
		if changed {
			if err := os.WriteFile(absPath, result, 0644); err != nil {
				return err
			}
		}
		if options.ListDiff {
			fmt.Println(absPath)
		}
	}

	return nil
}

func printUsageAndExit() {
	flag.Usage()
}
GOEOF

