package reviser

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// Options holds the configuration for the reviser
type Options struct {
	ProjectName           string
	CompanyPrefixes       string
	ImportsOrder          string
	Output                string
	ListDiff              bool
	SetExitStatus         bool
	RemoveUnused          bool
	SetAlias              bool
	Format                bool
	Recursive             bool
	ApplyToGeneratedFiles bool
	SeparateNamed         bool
	Excludes              string
	UseCache              bool
}

// stdPackages holds the set of Go standard library packages
var stdPackages map[string]bool

func init() {
	stdPackages = make(map[string]bool)
	for _, pkg := range knownStdPackages {
		stdPackages[pkg] = true
	}
}

// isStdPackage returns true if the import path is a standard library package
func isStdPackage(importPath string) bool {
	// A stdlib package either has no dot in the first segment, 
	// or is in our known list
	clean := strings.Trim(importPath, "\"")

	// Check our known list first
	if stdPackages[clean] {
		return true
	}

	// Heuristic: if the first path segment has no dot, it's stdlib
	parts := strings.SplitN(clean, "/", 2)
	if len(parts) > 0 && !strings.Contains(parts[0], ".") {
		return true
	}

	return false
}

// importInfo holds information about a single import
type importInfo struct {
	alias   string // alias (empty string if none, "_" for blank, "." for dot)
	path    string // import path (without quotes)
	comment string // trailing comment if any
	hasDoc  bool   // whether there was a doc comment (we drop these)
}

func (i importInfo) localName() string {
	if i.alias != "" {
		return i.alias
	}
	// Use last segment of path
	parts := strings.Split(i.path, "/")
	name := parts[len(parts)-1]
	// Handle versioned packages: strip the version suffix
	// e.g., "v2" -> use the second-to-last segment
	if strings.HasPrefix(name, "v") && len(name) > 1 {
		allDigits := true
		for _, c := range name[1:] {
			if c < '0' || c > '9' {
				allDigits = false
				break
			}
		}
		if allDigits && len(parts) > 1 {
			name = parts[len(parts)-2]
		}
	}
	return name
}

func (i importInfo) isBlank() bool {
	return i.alias == "_"
}

func (i importInfo) isDot() bool {
	return i.alias == "."
}

func (i importInfo) isNamed() bool {
	return i.alias != "" && i.alias != "_" && i.alias != "."
}

func (i importInfo) formatImport() string {
	if i.alias != "" {
		s := fmt.Sprintf("%s %q", i.alias, i.path)
		if i.comment != "" {
			s += " " + i.comment
		}
		return s
	}
	s := fmt.Sprintf("%q", i.path)
	if i.comment != "" {
		s += " " + i.comment
	}
	return s
}

// groupType represents the type of an import group
type groupType int

const (
	groupStd     groupType = iota
	groupGeneral groupType = iota
	groupCompany groupType = iota
	groupProject groupType = iota
	groupBlanked groupType = iota
	groupDotted  groupType = iota
)

func parseGroupType(s string) groupType {
	switch strings.TrimSpace(s) {
	case "std":
		return groupStd
	case "general":
		return groupGeneral
	case "company":
		return groupCompany
	case "project":
		return groupProject
	case "blanked":
		return groupBlanked
	case "dotted":
		return groupDotted
	default:
		return groupGeneral
	}
}

// ProcessFile processes a single Go file
func ProcessFile(absPath string, opts Options) (changed bool, result []byte, err error) {
	src, err := os.ReadFile(absPath)
	if err != nil {
		return false, nil, err
	}

	result, err = processContent(absPath, src, opts)
	if err != nil {
		return false, nil, err
	}

	changed = !bytes.Equal(src, result)
	return changed, result, nil
}

// processContent processes the content of a Go file
func processContent(filePath string, src []byte, opts Options) ([]byte, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filePath, src, parser.ParseComments)
	if err != nil {
		return src, fmt.Errorf("package has an errors")
	}

	// Check if this is a generated file
	if !opts.ApplyToGeneratedFiles && isGeneratedFile(file) {
		return src, nil
	}

	// Get project name
	projectName := opts.ProjectName
	if projectName == "" {
		projectName, err = detectProjectName(filePath)
		if err != nil {
			return nil, fmt.Errorf("could not determine project name: %v", err)
		}
	}

	// Parse imports order
	orderParts := strings.Split(opts.ImportsOrder, ",")
	var groupOrder []groupType
	hasBlankedGroup := false
	hasDottedGroup := false
	for _, p := range orderParts {
		gt := parseGroupType(p)
		groupOrder = append(groupOrder, gt)
		if gt == groupBlanked {
			hasBlankedGroup = true
		}
		if gt == groupDotted {
			hasDottedGroup = true
		}
	}

	// Parse company prefixes
	var companyPrefixes []string
	if opts.CompanyPrefixes != "" {
		for _, p := range strings.Split(opts.CompanyPrefixes, ",") {
			p = strings.TrimSpace(p)
			if p != "" {
				companyPrefixes = append(companyPrefixes, p)
			}
		}
	}

	// Extract all imports from the file
	allImports := extractImports(fset, file, src)

	if len(allImports) == 0 {
		// No imports to process
		if opts.Format {
			formatted, err := formatCode(src)
			if err != nil {
				return src, nil
			}
			return formatted, nil
		}
		return src, nil
	}

	// Handle rm-unused
	if opts.RemoveUnused {
		usedNames := findUsedIdentifiers(file)
		allImports = removeUnused(allImports, usedNames)
	}

	// Handle set-alias
	if opts.SetAlias {
		allImports = setVersionAlias(allImports)
	}

	// Categorize imports
	groups := make(map[groupType][]importInfo)
	for _, imp := range allImports {
		gt := categorizeImport(imp, projectName, companyPrefixes, hasBlankedGroup, hasDottedGroup)
		groups[gt] = append(groups[gt], imp)
	}

	// Sort each group
	for gt := range groups {
		sort.Slice(groups[gt], func(i, j int) bool {
			return groups[gt][i].path < groups[gt][j].path
		})
	}

	// Build new import section with separate-named if needed
	var importLines []string
	for gi, gt := range groupOrder {
		imps, ok := groups[gt]
		if !ok || len(imps) == 0 {
			continue
		}

		// Check if there are non-empty groups before this
		hasGroups := len(importLines) > 0

		if hasGroups {
			importLines = append(importLines, "")
		}

		if opts.SeparateNamed {
			// Separate named from unnamed within the group
			var unnamed, named []importInfo
			for _, imp := range imps {
				if imp.isNamed() {
					named = append(named, imp)
				} else {
					unnamed = append(unnamed, imp)
				}
			}
			for _, imp := range unnamed {
				importLines = append(importLines, "\t"+imp.formatImport())
			}
			if len(unnamed) > 0 && len(named) > 0 {
				importLines = append(importLines, "")
			}
			for _, imp := range named {
				importLines = append(importLines, "\t"+imp.formatImport())
			}
		} else {
			for _, imp := range imps {
				importLines = append(importLines, "\t"+imp.formatImport())
			}
		}
		_ = gi
	}

	// Rebuild the file
	newContent, err := rebuildFile(fset, file, src, importLines)
	if err != nil {
		return src, err
	}

	// Apply formatting if requested
	if opts.Format {
		formatted, err := formatCode(newContent)
		if err == nil {
			newContent = formatted
		}
	}

	return newContent, nil
}

// isGeneratedFile returns true if the file has a "// Code generated" comment at the top
func isGeneratedFile(file *ast.File) bool {
	for _, cg := range file.Comments {
		if cg.Pos() > file.Package {
			break
		}
		for _, c := range cg.List {
			if strings.HasPrefix(c.Text, "// Code generated") {
				return true
			}
		}
	}
	return false
}

// detectProjectName reads the module name from go.mod
func detectProjectName(filePath string) (string, error) {
	// If path is absolute, search from file's dir upward
	// If path is relative, search in CWD only (open "go.mod")

	if filepath.IsAbs(filePath) {
		dir := filepath.Dir(filePath)
		for {
			gomodPath := filepath.Join(dir, "go.mod")
			data, err := os.ReadFile(gomodPath)
			if err == nil {
				return parseModuleName(data), nil
			}
			parent := filepath.Dir(dir)
			if parent == dir {
				break
			}
			dir = parent
		}
		return "", fmt.Errorf("open go.mod: no such file or directory")
	}

	// Relative path: open go.mod in CWD
	data, err := os.ReadFile("go.mod")
	if err != nil {
		return "", err
	}
	return parseModuleName(data), nil
}

// parseModuleName extracts the module name from go.mod content
func parseModuleName(data []byte) string {
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "module ") {
			return strings.TrimSpace(line[7:])
		}
	}
	return ""
}

// extractImports extracts all import specs from the file
func extractImports(fset *token.FileSet, file *ast.File, src []byte) []importInfo {
	var imports []importInfo

	for _, decl := range file.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.IMPORT {
			continue
		}

		for _, spec := range genDecl.Specs {
			impSpec, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}

			imp := importInfo{}
			imp.path = strings.Trim(impSpec.Path.Value, "\"")

			if impSpec.Name != nil {
				imp.alias = impSpec.Name.Name
			}

			// Get inline comment
			if impSpec.Comment != nil {
				imp.comment = impSpec.Comment.Text()
			}

			imports = append(imports, imp)
		}
	}

	return imports
}

// findUsedIdentifiers returns a set of identifiers used in the file (outside imports)
func findUsedIdentifiers(file *ast.File) map[string]bool {
	used := make(map[string]bool)

	ast.Inspect(file, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.GenDecl:
			if x.Tok == token.IMPORT {
				return false // skip import declarations
			}
		case *ast.SelectorExpr:
			if ident, ok := x.X.(*ast.Ident); ok {
				used[ident.Name] = true
			}
			return true
		case *ast.Ident:
			used[x.Name] = true
		}
		return true
	})

	return used
}

// removeUnused removes imports that are not used in the file
func removeUnused(imports []importInfo, usedNames map[string]bool) []importInfo {
	var result []importInfo
	for _, imp := range imports {
		// Blank and dot imports are always kept
		if imp.isBlank() || imp.isDot() {
			result = append(result, imp)
			continue
		}

		name := imp.localName()
		if usedNames[name] {
			result = append(result, imp)
		}
	}
	return result
}

// setVersionAlias sets alias for versioned package names
func setVersionAlias(imports []importInfo) []importInfo {
	for i, imp := range imports {
		if imp.alias != "" {
			continue // already has alias
		}

		parts := strings.Split(imp.path, "/")
		if len(parts) == 0 {
			continue
		}

		lastPart := parts[len(parts)-1]
		// Check if last part is a version like v2, v3, etc.
		if strings.HasPrefix(lastPart, "v") && len(lastPart) > 1 {
			allDigits := true
			for _, c := range lastPart[1:] {
				if c < '0' || c > '9' {
					allDigits = false
					break
				}
			}
			if allDigits && len(parts) > 1 {
				// Set alias to the package name (second to last segment)
				imports[i].alias = parts[len(parts)-2]
			}
		}
	}
	return imports
}

// categorizeImport determines which group an import belongs to
func categorizeImport(imp importInfo, projectName string, companyPrefixes []string, hasBlankedGroup, hasDottedGroup bool) groupType {
	// If blanked/dotted groups exist in order, use them
	if hasBlankedGroup && imp.isBlank() {
		return groupBlanked
	}
	if hasDottedGroup && imp.isDot() {
		return groupDotted
	}

	path := imp.path

	// Check if it's a project import
	if projectName != "" && strings.HasPrefix(path, projectName) {
		return groupProject
	}

	// Check if it's stdlib
	if isStdPackage(path) {
		return groupStd
	}

	// Check company prefixes
	for _, prefix := range companyPrefixes {
		if strings.HasPrefix(path, prefix) {
			return groupCompany
		}
	}

	return groupGeneral
}

// rebuildFile rebuilds the Go file with new import lines
func rebuildFile(fset *token.FileSet, file *ast.File, src []byte, importLines []string) ([]byte, error) {
	// Find the position of the import declarations in the source
	// We need to replace all import blocks with a single new one

	if len(file.Decls) == 0 {
		return src, nil
	}

	// Find the start and end positions of all import declarations
	var importStart, importEnd token.Pos
	hasImports := false

	for _, decl := range file.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.IMPORT {
			continue
		}

		if !hasImports {
			importStart = genDecl.Pos()
			importEnd = genDecl.End()
			hasImports = true
		} else {
			if genDecl.End() > importEnd {
				importEnd = genDecl.End()
			}
		}
	}

	if !hasImports {
		if len(importLines) == 0 {
			return src, nil
		}
		// Need to add imports - complex case, skip for now
		return src, nil
	}

	startOffset := fset.Position(importStart).Offset
	endOffset := fset.Position(importEnd).Offset

	// Extend endOffset to include any trailing newline
	for endOffset < len(src) && (src[endOffset] == '\n' || src[endOffset] == '\r') {
		endOffset++
	}

	// Build the new import block
	var newImport string
	if len(importLines) == 0 {
		newImport = ""
	} else {
		var sb strings.Builder
		sb.WriteString("import (\n")
		for _, line := range importLines {
			sb.WriteString(line)
			sb.WriteString("\n")
		}
		sb.WriteString(")")
		newImport = sb.String()
	}

	// Replace the import section
	var buf bytes.Buffer
	buf.Write(src[:startOffset])
	buf.WriteString(newImport)
	if len(src) > endOffset {
		// Add newline separator if the remaining content doesn't start with newline
		remaining := src[endOffset:]
		if newImport != "" && len(remaining) > 0 && remaining[0] != '\n' {
			buf.WriteByte('\n')
		}
		buf.Write(remaining)
	}

	return buf.Bytes(), nil
}

// formatCode applies gofmt formatting to the source
func formatCode(src []byte) ([]byte, error) {
	return format.Source(src)
}

// ProcessDirectory processes all Go files in a directory
func ProcessDirectory(dir string, recursive bool, opts Options) (changed bool, err error) {
	// Parse excludes
	var excludePatterns []string
	if opts.Excludes != "" {
		for _, p := range strings.Split(opts.Excludes, ",") {
			p = strings.TrimSpace(p)
			if p != "" {
				excludePatterns = append(excludePatterns, p)
			}
		}
	}

	return processDir(dir, recursive, excludePatterns, opts)
}

func processDir(dir string, recursive bool, excludes []string, opts Options) (changed bool, err error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return false, err
	}

	for _, entry := range entries {
		name := entry.Name()
		path := filepath.Join(dir, name)

		// Check excludes
		if isExcluded(path, excludes) {
			continue
		}

		if entry.IsDir() {
			if recursive {
				subChanged, err := processDir(path, recursive, excludes, opts)
				if err != nil {
					continue
				}
				if subChanged {
					changed = true
				}
			}
			continue
		}

		if !strings.HasSuffix(name, ".go") {
			continue
		}

		absPath, err := filepath.Abs(path)
		if err != nil {
			continue
		}

		fileChanged, result, err := ProcessFile(absPath, opts)
		if err != nil {
			continue
		}

		if fileChanged {
			changed = true
		}

		handleOutput(absPath, fileChanged, result, opts)
	}

	return changed, nil
}

func handleOutput(absPath string, changed bool, result []byte, opts Options) {
	switch opts.Output {
	case "stdout":
		fmt.Print(string(result))
	case "write":
		if opts.ListDiff {
			fmt.Println(absPath)
		}
		if changed {
			os.WriteFile(absPath, result, 0644)
		}
	case "file", "":
		if changed {
			os.WriteFile(absPath, result, 0644)
		}
		if opts.ListDiff {
			fmt.Println(absPath)
		}
	}
}

func isExcluded(path string, patterns []string) bool {
	for _, pattern := range patterns {
		// Check if the path matches the pattern
		// The pattern can be a prefix (like ".git/") or a glob (like "proto/*.go")
		if strings.HasSuffix(pattern, "/") {
			// Directory pattern
			if strings.Contains(path, pattern) || strings.HasSuffix(path, strings.TrimSuffix(pattern, "/")) {
				return true
			}
		} else {
			// File pattern - use filepath.Match
			base := filepath.Base(path)
			matched, _ := filepath.Match(pattern, base)
			if matched {
				return true
			}
			// Also match against the full path
			matched, _ = filepath.Match("*/"+pattern, path)
			if matched {
				return true
			}
		}
	}
	return false
}
