	var excludePatterns []string
	if opts.Excludes != "" {
		for _, p := range strings.Split(opts.Excludes, ",") {
			p = strings.TrimSpace(p)
			if p != "" {
				excludePatterns = append(excludePatterns, p)
			}
		}
	}

	return processDir(dir, recursive, excludePatterns, opts)
