func processDir(dir string, recursive bool, excludes []string, opts Options) (changed bool, err error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return false, err
	}

	for _, entry := range entries {
		name := entry.Name()
		path := filepath.Join(dir, name)

		// Check excludes
		if isExcluded(path, excludes) {
			continue
		}

		if entry.IsDir() {
			if recursive {
				subChanged, err := processDir(path, recursive, excludes, opts)
				if err != nil {
					continue
				}
				if subChanged {
					changed = true
				}
			}
			continue
		}

		if !strings.HasSuffix(name, ".go") {
			continue
		}

		absPath, err := filepath.Abs(path)
		if err != nil {
			continue
		}

		fileChanged, result, err := ProcessFile(absPath, opts)
		if err != nil {
			continue
		}

		if fileChanged {
			changed = true
		}

		handleOutput(absPath, fileChanged, result, opts)
	}

	return changed, nil
}

func handleOutput(absPath string, changed bool, result []byte, opts Options) {
	switch opts.Output {
	case "stdout":
		fmt.Print(string(result))
	case "write":
		if opts.ListDiff {
			fmt.Println(absPath)
		}
		if changed {
			os.WriteFile(absPath, result, 0644)
		}
	case "file", "":
		if changed {
			os.WriteFile(absPath, result, 0644)
		}
		if opts.ListDiff {
			fmt.Println(absPath)
		}
	}
}

func isExcluded(path string, patterns []string) bool {
	for _, pattern := range patterns {
		// Check if the path matches the pattern
		// The pattern can be a prefix (like ".git/") or a glob (like "proto/*.go")
		if strings.HasSuffix(pattern, "/") {
			// Directory pattern
			if strings.Contains(path, pattern) || strings.HasSuffix(path, strings.TrimSuffix(pattern, "/")) {
				return true
			}
		} else {
			// File pattern - use filepath.Match
			base := filepath.Base(path)
			matched, _ := filepath.Match(pattern, base)
			if matched {
				return true
			}
			// Also match against the full path
			matched, _ = filepath.Match("*/"+pattern, path)
			if matched {
				return true
			}
		}
	}
	return false
}
