	for _, p := range orderParts {
		gt := parseGroupType(p)
		groupOrder = append(groupOrder, gt)
		if gt == groupBlanked {
			hasBlankedGroup = true
		}
		if gt == groupDotted {
			hasDottedGroup = true
		}
