// isGeneratedFile returns true if the file has a "// Code generated" comment at the top
func isGeneratedFile(file *ast.File) bool {
	for _, cg := range file.Comments {
		if cg.Pos() > file.Package {
			break
		}
		for _, c := range cg.List {
			if strings.HasPrefix(c.Text, "// Code generated") {
				return true
			}
		}
	}
	return false
}

// detectProjectName reads the module name from go.mod
func detectProjectName(filePath string) (string, error) {
	// If path is absolute, search from file's dir upward
	// If path is relative, search in CWD only (open "go.mod")

	if filepath.IsAbs(filePath) {
		dir := filepath.Dir(filePath)
		for {
			gomodPath := filepath.Join(dir, "go.mod")
			data, err := os.ReadFile(gomodPath)
			if err == nil {
				return parseModuleName(data), nil
			}
			parent := filepath.Dir(dir)
			if parent == dir {
				break
			}
			dir = parent
		}
		return "", fmt.Errorf("open go.mod: no such file or directory")
	}

	// Relative path: open go.mod in CWD
	data, err := os.ReadFile("go.mod")
	if err != nil {
		return "", err
	}
	return parseModuleName(data), nil
}

// parseModuleName extracts the module name from go.mod content
func parseModuleName(data []byte) string {
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "module ") {
			return strings.TrimSpace(line[7:])
		}
	}
	return ""
}

// extractImports extracts all import specs from the file
func extractImports(fset *token.FileSet, file *ast.File, src []byte) []importInfo {
	var imports []importInfo

	for _, decl := range file.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.IMPORT {
			continue
		}

		for _, spec := range genDecl.Specs {
			impSpec, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}

			imp := importInfo{}
			imp.path = strings.Trim(impSpec.Path.Value, "\"")

			if impSpec.Name != nil {
				imp.alias = impSpec.Name.Name
			}

			// Get inline comment
			if impSpec.Comment != nil {
				imp.comment = impSpec.Comment.Text()
			}

			imports = append(imports, imp)
		}
	}

	return imports
}

// findUsedIdentifiers returns a set of identifiers used in the file (outside imports)
func findUsedIdentifiers(file *ast.File) map[string]bool {
	used := make(map[string]bool)

	ast.Inspect(file, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.GenDecl:
			if x.Tok == token.IMPORT {
				return false // skip import declarations
			}
		case *ast.SelectorExpr:
			if ident, ok := x.X.(*ast.Ident); ok {
				used[ident.Name] = true
			}
			return true
		case *ast.Ident:
			used[x.Name] = true
		}
		return true
	})

	return used
}

// removeUnused removes imports that are not used in the file
func removeUnused(imports []importInfo, usedNames map[string]bool) []importInfo {
	var result []importInfo
	for _, imp := range imports {
		// Blank and dot imports are always kept
		if imp.isBlank() || imp.isDot() {
			result = append(result, imp)
			continue
		}

		name := imp.localName()
		if usedNames[name] {
			result = append(result, imp)
		}
	}
	return result
}

// setVersionAlias sets alias for versioned package names
func setVersionAlias(imports []importInfo) []importInfo {
	for i, imp := range imports {
		if imp.alias != "" {
			continue // already has alias
		}

		parts := strings.Split(imp.path, "/")
		if len(parts) == 0 {
			continue
		}

		lastPart := parts[len(parts)-1]
		// Check if last part is a version like v2, v3, etc.
		if strings.HasPrefix(lastPart, "v") && len(lastPart) > 1 {
			allDigits := true
			for _, c := range lastPart[1:] {
				if c < '0' || c > '9' {
					allDigits = false
					break
				}
			}
			if allDigits && len(parts) > 1 {
				// Set alias to the package name (second to last segment)
				imports[i].alias = parts[len(parts)-2]
			}
		}
	}
	return imports
}

// categorizeImport determines which group an import belongs to
func categorizeImport(imp importInfo, projectName string, companyPrefixes []string, hasBlankedGroup, hasDottedGroup bool) groupType {
	// If blanked/dotted groups exist in order, use them
	if hasBlankedGroup && imp.isBlank() {
		return groupBlanked
	}
	if hasDottedGroup && imp.isDot() {
		return groupDotted
	}

	path := imp.path

	// Check if it's a project import
	if projectName != "" && strings.HasPrefix(path, projectName) {
		return groupProject
	}

	// Check if it's stdlib
	if isStdPackage(path) {
		return groupStd
	}

	// Check company prefixes
	for _, prefix := range companyPrefixes {
		if strings.HasPrefix(path, prefix) {
			return groupCompany
		}
	}

	return groupGeneral
}

// rebuildFile rebuilds the Go file with new import lines
func rebuildFile(fset *token.FileSet, file *ast.File, src []byte, importLines []string) ([]byte, error) {
	// Find the position of the import declarations in the source
	// We need to replace all import blocks with a single new one

	if len(file.Decls) == 0 {
		return src, nil
	}

	// Find the start and end positions of all import declarations
	var importStart, importEnd token.Pos
	hasImports := false

	for _, decl := range file.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.IMPORT {
			continue
		}

		if !hasImports {
			importStart = genDecl.Pos()
			importEnd = genDecl.End()
			hasImports = true
		} else {
			if genDecl.End() > importEnd {
				importEnd = genDecl.End()
			}
		}
	}

	if !hasImports {
		if len(importLines) == 0 {
			return src, nil
		}
		// Need to add imports - complex case, skip for now
		return src, nil
	}

	startOffset := fset.Position(importStart).Offset
	endOffset := fset.Position(importEnd).Offset

	// Extend endOffset to include any trailing newline
	for endOffset < len(src) && (src[endOffset] == '\n' || src[endOffset] == '\r') {
		endOffset++
	}

	// Build the new import block
	var newImport string
	if len(importLines) == 0 {
		newImport = ""
	} else {
		var sb strings.Builder
		sb.WriteString("import (\n")
		for _, line := range importLines {
			sb.WriteString(line)
			sb.WriteString("\n")
		}
		sb.WriteString(")")
		newImport = sb.String()
	}

	// Replace the import section
	var buf bytes.Buffer
	buf.Write(src[:startOffset])
	buf.WriteString(newImport)
	if len(src) > endOffset {
		// Add newline separator if the remaining content doesn't start with newline
		remaining := src[endOffset:]
		if newImport != "" && len(remaining) > 0 && remaining[0] != '\n' {
			buf.WriteByte('\n')
		}
		buf.Write(remaining)
	}

	return buf.Bytes(), nil
}

// formatCode applies gofmt formatting to the source
func formatCode(src []byte) ([]byte, error) {
	return format.Source(src)
