package main

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/format"
	"go/parser"
	"go/token"
)

func insertBlanksBetweenDecls(src []byte) ([]byte, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", src, parser.ParseComments)
	if err != nil {
		return src, err
	}

	if len(f.Decls) <= 1 {
		return src, nil
	}

	// First, get the formatted source using gofmt
	formattedSrc, err := format.Source(src)
	if err != nil {
		return src, err
	}

	// Re-parse the formatted source to get accurate positions
	fset2 := token.NewFileSet()
	f2, err := parser.ParseFile(fset2, "", formattedSrc, parser.ParseComments)
	if err != nil {
		return formattedSrc, err
	}

	// Find top-level declaration positions
	type declPos struct {
		startLine int
		endLine   int
	}

	var positions []declPos
	for _, decl := range f2.Decls {
		start := fset2.Position(decl.Pos()).Line
		end := fset2.Position(decl.End()).Line
		positions = append(positions, declPos{start, end})
	}

	// Split source into lines
	lines := bytes.Split(formattedSrc, []byte("\n"))

	// Find pairs that need blank lines inserted
	type insertion struct {
		afterLine int // insert blank line after this line (1-based)
	}
	var insertions []insertion

	for i := 1; i < len(positions); i++ {
		prevEnd := positions[i-1].endLine
		curStart := positions[i].startLine
		if curStart == prevEnd+1 {
			// No blank line between them - need to insert one
			insertions = append(insertions, insertion{prevEnd})
		}
	}

	if len(insertions) == 0 {
		return formattedSrc, nil
	}

	// Insert blank lines
	insertSet := make(map[int]bool)
	for _, ins := range insertions {
		insertSet[ins.afterLine] = true
	}

	var result [][]byte
	for i, line := range lines {
		lineNum := i + 1
		result = append(result, line)
		if insertSet[lineNum] {
			result = append(result, []byte{})
		}
	}

	return bytes.Join(result, []byte("\n")), nil
}

func main() {
	src := []byte("package main\nfunc A(){\n}\nfunc B(){\n}\n")
	result, err := insertBlanksBetweenDecls(src)
	if err != nil {
		panic(err)
	}
	fmt.Println(string(result))

	_ = ast.File{}
}
EOF
