# Case 4: comment before func B gets blank line inserted between A and comment

# So the pattern seems to be:
# - gofmt is always applied first
# - Then: look at the GOFMT output to find consecutive top-level declarations
# - Insert blank lines between them UNLESS a trailing comment on the previous decl's last line
#   is making them "share" a line somehow

# Actually, let me think about this differently.
# The goimports format functionality is essentially:
# Use a go/printer with different behavior that inserts blank lines.

# OR: it modifies the AST before printing to adjust line numbers.

# Let me try a different approach: use go/printer with modified positions.
# The key is: if we mark the declarations as being further apart in the source,
# the printer will add blank lines.

# Actually the simplest fix for my algorithm: after gofmt, check if the
# LAST LINE of the previous decl (which includes any inline comments) 
# and the FIRST LINE of the next decl have no blank line between them.

# But the check should consider Comment END positions too.
# Let me try: look at all the comments attached to declarations.

cat > /tmp/testdeclpos.go << 'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

func main() {
	cases := []string{
		"package main\nfunc A() {}\nfunc B() {}\n",
		"package main\nfunc A() {} // comment\nfunc B() {}\n",
		"package main\nfunc A() {\n}\nfunc B() {}\n",
	}

	for _, src := range cases {
		fset := token.NewFileSet()
		f, _ := parser.ParseFile(fset, "", src, parser.ParseComments)
		fmt.Printf("Source:\n%s\n", src)
		for i, decl := range f.Decls {
			start := fset.Position(decl.Pos())
			end := fset.Position(decl.End())
			fmt.Printf("  Decl %d: start=%d end=%d\n", i, start.Line, end.Line)
		}
		// Print comment positions
		for _, cg := range f.Comments {
			for _, c := range cg.List {
				pos := fset.Position(c.Pos())
				fmt.Printf("  Comment %q at line %d\n", c.Text, pos.Line)
			}
		}
		fmt.Println("---")
	}
	_ = ast.File{}
}
EOF
