package main

import (
	"fmt"
	"go/parser"
	"go/token"
	"strings"
)

var knownStdPkgs = map[string]bool{
	"bytes": true,
	"fmt":   true,
}

func isStd(path string) bool {
	if knownStdPkgs[path] {
		return true
	}
	parts := strings.SplitN(path, "/", 2)
	if len(parts) > 0 && !strings.Contains(parts[0], ".") {
		return true
	}
	return false
}

func main() {
	src := `package main

import (
	"fmt" // fmt comment
	"bytes" // bytes comment
	"github.com/myproject/test/pkg" // project comment
	"github.com/some/external" // external comment
)

func test() {
	fmt.Println("")
	_ = bytes.NewBuffer(nil)
}`

	fset := token.NewFileSet()
	f, _ := parser.ParseFile(fset, "", src, parser.ParseComments)

	for _, imp := range f.Imports {
		path := strings.Trim(imp.Path.Value, "\"")
		var comment string
		if imp.Comment != nil {
			for _, c := range imp.Comment.List {
				comment = c.Text
			}
		}
		fmt.Printf("import %q, comment=%q, isStd=%v\n", path, comment, isStd(path))
	}
}
EOF
