	var importLines []string
	firstGroup := true
	for _, gt := range groupOrder {
		imps, ok := groups[gt]
		if !ok || len(imps) == 0 {
			continue
		}

		if !firstGroup {
			importLines = append(importLines, "")
		}
		firstGroup = false

