	first := file.Comments[0]
	if len(first.List) == 0 {
		return false
	}
	return strings.HasPrefix(first.List[0].Text, "// Code generated")
}

// detectProjectName reads the module name from go.mod
func detectProjectName(filePath string) (string, error) {
	if filepath.IsAbs(filePath) {
		dir := filepath.Dir(filePath)
		for {
			gomodPath := filepath.Join(dir, "go.mod")
			data, err := os.ReadFile(gomodPath)
			if err == nil {
				return parseModuleName(data), nil
			}
			parent := filepath.Dir(dir)
			if parent == dir {
				break
			}
			dir = parent
		}
		return "", fmt.Errorf("open go.mod: no such file or directory")
	}

	// Relative path: open go.mod in CWD only
	data, err := os.ReadFile("go.mod")
	if err != nil {
		return "", err
	}
	return parseModuleName(data), nil
}

// parseModuleName extracts the module name from go.mod content
func parseModuleName(data []byte) string {
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "module ") {
			return strings.TrimSpace(line[7:])
		}
	}
	return ""
}

// extractImports extracts all import specs from the file
func extractImports(file *ast.File) []importInfo {
	var imports []importInfo

	for _, decl := range file.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.IMPORT {
			continue
		}

		for _, spec := range genDecl.Specs {
			impSpec, ok := spec.(*ast.ImportSpec)
			if !ok {
				continue
			}

			imp := importInfo{}
			imp.path = strings.Trim(impSpec.Path.Value, "\"")

			if impSpec.Name != nil {
				imp.alias = impSpec.Name.Name
			}

			// Get inline comment (raw text, including "//")
			if impSpec.Comment != nil && len(impSpec.Comment.List) > 0 {
				imp.comment = impSpec.Comment.List[0].Text
			}

			imports = append(imports, imp)
		}
	}

	return imports
}

// findUsedIdentifiers returns a set of package names used in the file (outside imports)
func findUsedIdentifiers(file *ast.File) map[string]bool {
	used := make(map[string]bool)

	ast.Inspect(file, func(n ast.Node) bool {
		switch x := n.(type) {
		case *ast.GenDecl:
			if x.Tok == token.IMPORT {
				return false
			}
		case *ast.SelectorExpr:
			if ident, ok := x.X.(*ast.Ident); ok {
				used[ident.Name] = true
			}
			return true
		}
		return true
	})

	return used
}

// removeUnused removes imports not used in the file
func removeUnused(imports []importInfo, usedNames map[string]bool) []importInfo {
	var result []importInfo
	for _, imp := range imports {
		if imp.isBlank() || imp.isDot() {
			result = append(result, imp)
			continue
		}
		if usedNames[imp.localName()] {
			result = append(result, imp)
		}
	}
	return result
}

// setVersionAlias sets alias for versioned package names
func setVersionAlias(imports []importInfo) []importInfo {
	for i, imp := range imports {
		if imp.alias != "" {
			continue
		}
		parts := strings.Split(imp.path, "/")
		if len(parts) == 0 {
			continue
		}
		lastPart := parts[len(parts)-1]
		if strings.HasPrefix(lastPart, "v") && len(lastPart) > 1 {
			allDigits := true
			for _, c := range lastPart[1:] {
				if c < '0' || c > '9' {
					allDigits = false
					break
				}
			}
			if allDigits && len(parts) > 1 {
				imports[i].alias = parts[len(parts)-2]
			}
		}
	}
	return imports
}

// categorizeImport determines which group an import belongs to
func categorizeImport(imp importInfo, projectName string, companyPrefixes []string, hasBlankedGroup, hasDottedGroup bool) groupType {
	if hasBlankedGroup && imp.isBlank() {
		return groupBlanked
	}
	if hasDottedGroup && imp.isDot() {
		return groupDotted
	}

	path := imp.path

	if projectName != "" && (path == projectName || strings.HasPrefix(path, projectName+"/")) {
		return groupProject
	}

	if isStdPackage(path) {
		return groupStd
	}

	for _, prefix := range companyPrefixes {
		if strings.HasPrefix(path, prefix) {
			return groupCompany
		}
	}

	return groupGeneral
}

// rebuildFile rebuilds the Go file with new import lines
func rebuildFile(fset *token.FileSet, file *ast.File, src []byte, importLines []string) ([]byte, error) {
	// Find the first and last import declaration
	var firstImport, lastImport *ast.GenDecl
	for _, decl := range file.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.IMPORT {
			continue
		}
		if firstImport == nil {
			firstImport = genDecl
		}
		lastImport = genDecl
	}

	if firstImport == nil {
		return src, nil
	}

	startOffset := fset.Position(firstImport.Pos()).Offset
	endOffset := fset.Position(lastImport.End()).Offset

	// Build the new import block
	var newImport string
	if len(importLines) == 0 {
		// Remove imports entirely
		newImport = ""
	} else {
		var sb strings.Builder
		sb.WriteString("import (\n")
		for _, line := range importLines {
			sb.WriteString(line)
			sb.WriteString("\n")
		}
		sb.WriteString(")")
		newImport = sb.String()
	}

	// Replace the import section
	var buf bytes.Buffer
	buf.Write(src[:startOffset])
	buf.WriteString(newImport)
	buf.Write(src[endOffset:])

	return buf.Bytes(), nil
}

// formatCode applies gofmt formatting to the source
func formatCode(src []byte) ([]byte, error) {
	return format.Source(src)
}

// insertBlanksBetweenDecls inserts blank lines between consecutive top-level declarations
// This implements the behavior of goimports -format option
func insertBlanksBetweenDecls(src []byte) ([]byte, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", src, parser.ParseComments)
	if err != nil {
		return src, err
	}

	if len(f.Decls) <= 1 {
		return src, nil
	}

	// Build map of lines that have comments
	commentLines := make(map[int]bool)
	for _, cg := range f.Comments {
		for _, c := range cg.List {
			commentLines[fset.Position(c.Pos()).Line] = true
		}
	}

	// Find pairs of adjacent decls that need blank lines
	insertAfterLines := make(map[int]bool)
	for i := 1; i < len(f.Decls); i++ {
		prevEnd := fset.Position(f.Decls[i-1].End()).Line
		curStart := fset.Position(f.Decls[i].Pos()).Line

		// Only insert if they're on consecutive lines AND no comment at the end of prev decl
		if curStart == prevEnd+1 && !commentLines[prevEnd] {
			insertAfterLines[prevEnd] = true
		}
	}

	if len(insertAfterLines) == 0 {
		return src, nil
	}

	// Split source into lines and insert blank lines
	lines := bytes.Split(src, []byte("\n"))
	var result [][]byte
	for i, line := range lines {
		lineNum := i + 1
		result = append(result, line)
		if insertAfterLines[lineNum] {
			result = append(result, []byte{})
		}
	}

	return bytes.Join(result, []byte("\n")), nil
}

// ProcessDirectory processes all Go files in a directory
func ProcessDirectory(dir string, recursive bool, opts Options) (changed bool, err error) {
	var excludePatterns []string
	if opts.Excludes != "" {
		for _, p := range strings.Split(opts.Excludes, ",") {
			p = strings.TrimSpace(p)
			if p != "" {
				excludePatterns = append(excludePatterns, p)
			}
		}
	}
	return processDir(dir, recursive, excludePatterns, opts)
}

func processDir(dir string, recursive bool, excludes []string, opts Options) (changed bool, err error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return false, err
	}

	for _, entry := range entries {
		name := entry.Name()
		path := filepath.Join(dir, name)

		if isExcluded(path, name, excludes) {
			continue
		}

		if entry.IsDir() {
			if recursive {
				subChanged, err := processDir(path, recursive, excludes, opts)
				if err != nil {
					continue
				}
				if subChanged {
					changed = true
				}
			}
			continue
		}

		if !strings.HasSuffix(name, ".go") {
			continue
		}

		absPath, err := filepath.Abs(path)
		if err != nil {
			continue
		}

		fileChanged, result, ferr := ProcessFile(absPath, opts)
		if ferr != nil {
			continue
		}

		if fileChanged {
			changed = true
		}

		handleOutput(absPath, fileChanged, result, opts)
	}

	return changed, nil
}

func handleOutput(absPath string, changed bool, result []byte, opts Options) {
	switch opts.Output {
	case "stdout":
		fmt.Print(string(result))
	case "write":
		if opts.ListDiff {
			fmt.Println(absPath)
		}
		if changed {
			os.WriteFile(absPath, result, 0644)
		}
	case "file", "":
		if changed {
			os.WriteFile(absPath, result, 0644)
		}
		if opts.ListDiff {
			fmt.Println(absPath)
		}
	}
}

func isExcluded(path, name string, patterns []string) bool {
	for _, pattern := range patterns {
		if strings.HasSuffix(pattern, "/") {
			dirName := strings.TrimSuffix(pattern, "/")
			if name == dirName {
				return true
			}
			// Check if any path component matches
			parts := strings.Split(filepath.ToSlash(path), "/")
			for _, part := range parts {
				if part == dirName {
					return true
				}
			}
		} else {
			// File pattern
			matched, _ := filepath.Match(pattern, name)
			if matched {
				return true
			}
		}
	}
	return false
}
