func insertBlanksBetweenDecls(src []byte) ([]byte, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "", src, parser.ParseComments)
	if err != nil {
		return src, err
	}

	if len(f.Decls) <= 1 {
		return src, nil
	}

	// Build map of lines that have comments
	commentLines := make(map[int]bool)
	for _, cg := range f.Comments {
		for _, c := range cg.List {
			commentLines[fset.Position(c.Pos()).Line] = true
		}
	}

	// Find pairs of adjacent decls that need blank lines
	insertAfterLines := make(map[int]bool)
	for i := 1; i < len(f.Decls); i++ {
		prevEnd := fset.Position(f.Decls[i-1].End()).Line
		curStart := fset.Position(f.Decls[i].Pos()).Line

		// Only insert if they're on consecutive lines AND no comment at the end of prev decl
		if curStart == prevEnd+1 && !commentLines[prevEnd] {
			insertAfterLines[prevEnd] = true
		}
	}

	if len(insertAfterLines) == 0 {
		return src, nil
	}

	// Split source into lines and insert blank lines
	lines := bytes.Split(src, []byte("\n"))
	var result [][]byte
	for i, line := range lines {
		lineNum := i + 1
		result = append(result, line)
		if insertAfterLines[lineNum] {
