		absPath, err := filepath.Abs(path)
		if err != nil {
			continue
		}

		fileChanged, result, ferr := ProcessFile(absPath, opts)
		if ferr != nil {
			continue
		}

		if fileChanged {
			changed = true
		}

		handleOutput(absPath, fileChanged, result, opts)
	}

	return changed, nil
