	}
	log.Fatalf("Failed to fix file: %s", err.Error())
}

func processPath(path string, opts reviser.Options) (changed bool, err error) {
	// Check if it's a directory
	info, statErr := os.Stat(path)
	if statErr == nil && info.IsDir() {
		dirChanged, err := reviser.ProcessDirectory(path, opts.Recursive, opts)
		if err != nil {
			return false, err
		}
		return dirChanged, nil
	}

	// It's a file (or doesn't exist - ProcessFile will handle the error)
	absPath, err := filepath.Abs(path)
	if err != nil {
		return false, err
	}

	fileChanged, result, err := reviser.ProcessFile(absPath, opts)
	if err != nil {
		return false, err
	}

	// Handle output for single file mode
	switch opts.Output {
	case "stdout":
		if opts.ListDiff && fileChanged {
			// When changed and list-diff: show filepath instead of content
			fmt.Println(absPath)
		} else {
			// Show content (normal stdout behavior)
			fmt.Print(string(result))
		}
	case "write":
		if opts.ListDiff {
			fmt.Println(absPath)
		}
		if fileChanged {
			if werr := os.WriteFile(absPath, result, 0644); werr != nil {
				return fileChanged, werr
			}
		}
	case "file", "":
		if fileChanged {
			if werr := os.WriteFile(absPath, result, 0644); werr != nil {
				return fileChanged, werr
			}
		}
		if opts.ListDiff {
			fmt.Println(absPath)
		}
	}

	return fileChanged, nil
}
