# When original has parens and gets reduced to one import: stays in parens!
# "import (\n\t\"fmt\"\n)"

# The ONLY case where it's "import \"fmt\"" is when the ORIGINAL SOURCE already has it that way.
# My implementation converts even "import \"fmt\"" to parens form.

# So my issue is: for a single un-parens import, I'm wrapping it in parens.

# The fix: detect if the original import block had parens or not.
# If original was "import \"fmt\"" (without parens, Lparen == NoPos), 
# keep it as single import format.

# Let me check the AST for single vs parens imports:
cat > /tmp/testastimport.go << 'EOF'
package main

import (
	"fmt"
	"go/parser"
	"go/token"
)

func main() {
	// Test single import
	src1 := "package main\nimport \"fmt\"\nfunc test() { fmt.Println(\"\") }\n"
	// Test parens import
	src2 := "package main\nimport (\n\t\"fmt\"\n)\nfunc test() { fmt.Println(\"\") }\n"

	for i, src := range []string{src1, src2} {
		fset := token.NewFileSet()
		f, _ := parser.ParseFile(fset, "", src, 0)
		for _, decl := range f.Decls {
			_ = decl
		}
		for _, imp := range f.Imports {
			pos := fset.Position(imp.Pos())
			fmt.Printf("Case %d: import %s, pos=%v\n", i+1, imp.Path.Value, pos)
		}
		// Check for GenDecl Lparen
		for _, decl := range f.Decls {
			type LparenChecker interface {
				LParen() token.Pos
			}
			// GenDecl
			_ = decl
		}
	}
}
EOF
cd /tmp && go run testastimport.go 2>&1

