func rebuildFile(fset *token.FileSet, file *ast.File, src []byte, importLines []string) ([]byte, error) {
	// Find the first and last import declaration
	var firstImport, lastImport *ast.GenDecl
	importCount := 0
	for _, decl := range file.Decls {
		genDecl, ok := decl.(*ast.GenDecl)
		if !ok || genDecl.Tok != token.IMPORT {
			continue
		}
		if firstImport == nil {
			firstImport = genDecl
		}
		lastImport = genDecl
		importCount++
	}

	if firstImport == nil {
		return src, nil
	}

	startOffset := fset.Position(firstImport.Pos()).Offset
	endOffset := fset.Position(lastImport.End()).Offset

	// Build the new import block
	var newImport string
	if len(importLines) == 0 {
		// Remove imports entirely
		newImport = ""
	} else if importCount == 1 && !firstImport.Lparen.IsValid() && len(importLines) == 1 {
		// Single import without parens: keep as "import path"
		// importLines[0] has the form \\t"path" or \\talias "path" 
		// We need to strip the leading tab
		line := strings.TrimLeft(importLines[0], "\\t")
		// Also strip any trailing comment since single-line imports don\'t need it
		// Actually keep it as-is but without the tab prefix
		newImport = "import " + line
	} else {
		var sb strings.Builder
		sb.WriteString("import (\\n")
		for _, line := range importLines {
