		seg := parts[0]
		if !strings.Contains(seg, ".") && !strings.Contains(seg, "-") {
			return true
		}
	}
	return false
}'''

new_isstd = '''// isStdPackage returns true if the import path is a standard library package
func isStdPackage(importPath string) bool {
	if stdPackages[importPath] {
		return true
	}
	// Heuristic: if the first path segment looks like a stdlib prefix (no dot, hyphen, or underscore),
	// it might be a stdlib package (covers future additions not in our known list)
	parts := strings.SplitN(importPath, "/", 2)
	if len(parts) > 0 {
		seg := parts[0]
		if !strings.Contains(seg, ".") && !strings.Contains(seg, "-") && !strings.Contains(seg, "_") {
			return true
		}
	}
	return false
}'''

content = content.replace(old_isstd, new_isstd)

with open('/workspace/myimpl/reviser/reviser.go', 'w') as f:
    f.write(content)

print("Done")
