	fmt.Printf("Package pos: %v\n", fset.Position(f.Package))
	for i, cg := range f.Comments {
		for j, c := range cg.List {
			pos := fset.Position(c.Pos())
			fmt.Printf("Comment %d.%d at line %d: %q (before_package=%v)\n", 
				i, j, pos.Line, c.Text, c.Pos() < f.Package)
		}
	}
	_ = ast.File{}
}
EOF
